const body = $json.body ?? $json;
const playerName = String(body.playerName ?? '').trim().replace(/\s+/g, ' ');
const score = Number(body.score);
const level = Number(body.level);
const timeRemaining = Number(body.timeRemaining);
const collectedItems = Number(body.collectedItems);
const result = String(body.result ?? '');
const playedAt = String(body.playedAt ?? '');
const levelName = String(body.levelName ?? '').trim();
const validationErrors = [];
if (playerName.length < 2 || playerName.length > 20) validationErrors.push('El nombre debe tener entre 2 y 20 caracteres.');
if (body.score === null || body.score === undefined || body.score === '' || !Number.isFinite(score) || score < 0 || score > 100000) validationErrors.push('El puntaje debe estar entre 0 y 100000.');
if (!Number.isInteger(level) || level < 1 || level > 3) validationErrors.push('El nivel debe ser un entero entre 1 y 3.');
if (!['won', 'lost'].includes(result)) validationErrors.push('El resultado debe ser won o lost.');
if (!playedAt || Number.isNaN(Date.parse(playedAt))) validationErrors.push('La fecha debe ser válida.');
if (!Number.isFinite(timeRemaining) || timeRemaining < 0) validationErrors.push('El tiempo restante debe ser un número no negativo.');
if (!Number.isInteger(collectedItems) || collectedItems < 0) validationErrors.push('Los objetos recogidos deben ser un entero no negativo.');
if (!levelName) validationErrors.push('El nombre del nivel es obligatorio.');
const badge = score >= 400 ? 'Leyenda del Pacífico' : score >= 250 ? 'Protector del Faro' : score >= 120 ? 'Guardián de la Bahía' : 'Marinero Novato';
const normalized = { playerName, score, level, levelName, result, timeRemaining, collectedItems, playedAt, badge };
return [{ json: { ...normalized, normalized, isValid: validationErrors.length === 0, validationErrors, badge } }];

const savedScore = $('Guardar puntaje').first().json;
const scores = $input.all().flatMap(item => Array.isArray(item.json) ? item.json : [item.json]);
const sorted = scores.filter(item => item && Number.isFinite(Number(item.score))).sort((a, b) => Number(b.score) - Number(a.score) || new Date(a.playedAt) - new Date(b.playedAt));
const position = sorted.findIndex(item => String(item.id) === String(savedScore.id)) + 1;
return [{ json: { success: true, message: 'Puntaje registrado correctamente', savedScore, position: position || 1, badge: savedScore.badge, topFive: sorted.slice(0, 5) } }];
